  Grid GameFirstHorizontalViewport(FrameworkElement child,string tag){
   child.HorizontalAlignment=HorizontalAlignment.Left;
   var grid=new Grid{Tag=tag};grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});
   var viewer=new ScrollViewer{Content=child,HorizontalScrollBarVisibility=ScrollBarVisibility.Hidden,VerticalScrollBarVisibility=ScrollBarVisibility.Disabled,Tag=tag+":scroll"};Grid.SetColumn(viewer,1);grid.Children.Add(viewer);
   var left=Button("‹",()=>viewer.ScrollToHorizontalOffset(Math.Max(0,viewer.HorizontalOffset-180)));var right=Button("›",()=>viewer.ScrollToHorizontalOffset(viewer.HorizontalOffset+180));
   foreach(var arrow in new[]{left,right}){arrow.Width=18;arrow.Height=35;arrow.Padding=new Thickness(0);arrow.Margin=new Thickness(0);arrow.FontSize=20;arrow.VerticalAlignment=VerticalAlignment.Top;arrow.Background=Brushes.Transparent;arrow.BorderThickness=new Thickness(0);arrow.Visibility=Visibility.Collapsed;}
   Grid.SetColumn(right,2);grid.Children.Add(left);grid.Children.Add(right);viewer.ScrollChanged+=(sender,args)=>{left.Visibility=viewer.HorizontalOffset>0?Visibility.Visible:Visibility.Collapsed;right.Visibility=viewer.HorizontalOffset<viewer.ScrollableWidth?Visibility.Visible:Visibility.Collapsed;};return grid;
  }
